#include "efs/raft.h"
#include "efs/raft_disk.h"
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/resource.h>
#include <dlfcn.h>
static unsigned long long measured_syncs,group_syncs[2];static int measuring;static unsigned active_group,group_acks[2];static double group_lat[2][2560];
int fdatasync(int fd){static int(*real_sync)(int);if(!real_sync)real_sync=dlsym(RTLD_NEXT,"fdatasync");assert(real_sync);int rc=real_sync(fd);if(measuring){assert(!rc);measured_syncs++;group_syncs[active_group]++;}return rc;}
static unsigned acks,offset;static struct efs_raft_disk *disk;
static double *lat,started;
static double now(void){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec+t.tv_nsec/1e9;}
static int send_reply(void *p,const struct efs_raft_msg*m){(void)p;if(m->success&&m->match_index){assert(m->match_index<=efs_raft_disk_covered_index(disk,m->group,efs_raft_disk_synced_bytes(disk)));assert(m->match_index>offset);double elapsed=(now()-started)*1e6;unsigned g=m->group/2;assert(g<2 && group_acks[g]<2560);lat[acks++]=elapsed;group_lat[g][group_acks[g]++]=elapsed;}return EFS_OK;}
static int cmp(const void*a,const void*b){double x=*(double*)a,y=*(double*)b;return(x>y)-(x<y);}
int main(int argc,char**argv){assert(argc==5);int batch=atoi(argv[1]);unsigned groups=atoi(argv[2]),width=atoi(argv[3]);assert((groups==1||groups==2)&&(width==1||width==16));char path[1024];assert(snprintf(path,sizeof(path),"%s/w93-cohort-XXXXXX",argv[4])<(int)sizeof(path));assert(mkdtemp(path));disk=efs_raft_disk_open(path,EFS_RAFT_DISK_SYNC);assert(disk);struct efs_raft *rafts[2];for(unsigned g=0;g<groups;g++){struct efs_raft_store*store=efs_raft_disk_group(disk,g*2);struct efs_raft_cfg cfg={0};cfg.id=1;cfg.n=3;cfg.group=g*2;cfg.election_ticks=10;cfg.heartbeat_ticks=1;cfg.store=store;cfg.store_ctx=store;cfg.send=send_reply;rafts[g]=efs_raft_new(&cfg);assert(rafts[g]);struct efs_raft_msg hello={0};hello.type=EFS_RAFT_MSG_AE_REQ;hello.from=0;hello.to=1;hello.group=g*2;hello.term=2;assert(efs_raft_recv(rafts[g],&hello)==EFS_OK);}char value[1024]={0};lat=calloc(2560,sizeof(double));assert(lat);measuring=1;double t=now();for(unsigned wave=0;wave<2560/width;wave++){unsigned g=wave%groups;active_group=g;offset=(wave/groups)*width;struct efs_raft_msg msgs[16]={0};for(unsigned i=0;i<width;i++){msgs[i].type=EFS_RAFT_MSG_AE_REQ;msgs[i].from=0;msgs[i].to=1;msgs[i].group=g*2;msgs[i].term=2;msgs[i].prev_index=offset+i;msgs[i].prev_term=offset+i?2:0;msgs[i].nentries=1;msgs[i].entries[0].term=2;msgs[i].entries[0].cmd=(uint8_t*)value;msgs[i].entries[0].clen=sizeof(value);}started=now();if(batch)assert(efs_raft_recv_batch(rafts[g],msgs,width)==EFS_OK);else for(unsigned i=0;i<width;i++)assert(efs_raft_recv(rafts[g],&msgs[i])==EFS_OK);}double elapsed=now()-t;measuring=0;assert(acks==2560);for(unsigned g=0;g<groups;g++)efs_raft_free(rafts[g]);efs_raft_disk_close(disk);disk=efs_raft_disk_open(path,EFS_RAFT_DISK_SYNC);assert(disk);for(unsigned g=0;g<groups;g++){struct efs_raft_store*store=efs_raft_disk_group(disk,g*2);for(unsigned i=1;i<=2560/groups;i++){char bytes[1024];uint32_t n=sizeof(bytes);uint64_t term;assert(store->get(store,i,&term,(uint8_t*)bytes,&n)==EFS_OK&&term==2&&n==sizeof(value)&&!memcmp(bytes,value,n));}}efs_raft_disk_close(disk);char file[1024];snprintf(file,sizeof(file),"%s/raft.log",path);assert(!unlink(file)&&!rmdir(path));qsort(lat,acks,sizeof(double),cmp);struct rusage usage;getrusage(RUSAGE_SELF,&usage);printf("{\"fdatasync_calls\":%llu,\"batch\":%d,\"groups\":%u,\"width\":%u,\"records\":%u,\"ops_s\":%.1f,\"ready_to_ack_p50_us\":%.1f,\"p95_us\":%.1f,\"p99_us\":%.1f,\"maxrss_kib\":%ld,\"by_group\":[",measured_syncs,batch,groups,width,acks,acks/elapsed,lat[acks/2],lat[acks*95/100],lat[acks*99/100],usage.ru_maxrss);for(unsigned g=0;g<groups;g++){assert(group_acks[g]==2560/groups);qsort(group_lat[g],group_acks[g],sizeof(double),cmp);printf("%s{\"group\":%u,\"records\":%u,\"fdatasync_calls\":%llu,\"ready_to_ack_p50_us\":%.1f,\"p95_us\":%.1f,\"p99_us\":%.1f}",g?",":"",g*2,group_acks[g],group_syncs[g],group_lat[g][group_acks[g]/2],group_lat[g][group_acks[g]*95/100],group_lat[g][group_acks[g]*99/100]);}puts("]}");free(lat);}
